        totalSum += bounds.get(i);
        if (i == bounds.size() - 1){
            suffixSum.add(totalSum);
        } else {
            suffixSum.add(suffixSum.get(suffixSum.size() - 1) - bounds.get(i));
        }
    }

    return new Pair<>(suffixSum, totalSum);
}

