public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        return 11; // smallest prime number
    }

    int capacity = desiredCapacity;
    if (capacity % 2 == 0) {
        capacity++;
    }

    while (!isPrime(capacity)) {
        capacity += 2;
    }

    // Ensure that the prime is within 11% of the desired capacity if it's >= 1000
    if (desiredCapacity >= 1000 && capacity > desiredCapacity + (desiredCapacity * 0.11)) {
        capacity = desiredCapacity + (desiredCapacity * 0.11);
        while (!isPrime(capacity)) {
            capacity += 2;
        }
    }

    return capacity;
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
